/* 
Open the Suggestions tab and choose a template to get started creating different content types for your pop-up. 
To learn more about using Arcade to create pop-up content visit: 
https://developers.arcgis.com/arcade/guide/profiles/#popup-element 
*/
var relatedRecords = FeatureSetByRelationshipName($feature, "BND1_EarlyVoting_County_to_Locations")

var popupString = ''

for (var f in relatedRecords){

	var zip = f.ZIP;
  var city =  f.CITY
  var address =  f.ADDRESS
	var location = f.EARLY_VOTING_LOCATION

	var note = f.NOTE ; // Field with your text string
	var fullText = note  + `<br>`
	var targetWord = "map";           // The specific word you want to linkify
	var destinationURL = f.HYPERLINK; // Field containing the hyperlink

	var fullAddress = Concatenate([address, city, 'DE', zip], ' ')

	var googleAddress = Replace(fullAddress, ' ', '+')

 	var fullUrl = `https://www.google.com/maps/search/?api=1&query=${googleAddress}`;

  var displayAddress2 = f.CITY + ', ' + f.STATE + ' ' + f.ZIP
	var displayAddress = `${address}<br>${displayAddress2}`

 	// Step 2: Build the HTML anchor tag
	var htmlLink = "<a href='" + destinationURL + "' target='_blank'>" + targetWord + "</a>";

	// Step 3: Replace the plain word with the HTML link version
	var richTextOutput =  IIF(IsEmpty(note), "", Replace(fullText, targetWord, htmlLink)) ;   

	var htmlText = `<b>${location}</b><br><a href=${fullUrl}>${displayAddress}</a><br>${richTextOutput}<br>`;

	popupString += htmlText + TextFormatting.NewLine;

}

//return popupString
return { 
	type : 'text', 
	text : `<p>${popupString}  <i>Click on address to open early voting sites in Google Maps</i></p>`
}

